  mode: AgentMode,
  selections: readonly CapabilityHintSelection[],
): { capabilities: CapabilityHintSelection[] } | undefined {
  if (mode !== "auto" || selections.length === 0) return undefined;
  return {
    capabilities: selections.map(({ kind, id }) => ({ kind, id })),
  };
}

