import { type FC, useEffect, useLayoutEffect, useRef, useState } from "react";
import {
  TextMessagePartProvider,
  useMessage,
  type TextMessagePart,
  type ToolCallMessagePart,
} from "@assistant-ui/react";
import {
  CheckIcon,
  ChevronDownIcon,
  CogIcon,
  LightbulbIcon,
  MoreHorizontalIcon,
  XIcon,
} from "lucide-react";

import {
  cn,
  useOptionalAomiRuntime,
  useThreadTaskRuns,
  type TaskRunState,
} from "@aomi-labs/react";
import { MarkdownText } from "@/components/assistant-ui/markdown-text";
import { interpretToolStep } from "@/components/assistant-ui/tool-interpreter";
import {
  agentStepCount,
  WorkingAgent,
} from "@/components/assistant-ui/working-agent";
import {
  prefersReducedMotion,
  toDetailString,
  ToolStepRow,
  WorkingNote,
} from "@/components/assistant-ui/working-trace-rows";

/**
 * Working trace — the chain-of-thought UI.
 *
 * A merged assistant turn (see `mergeAssistantTurns` in @aomi-labs/react) is one
 * message with ordered parts `[tool-call, …, text]`. We split it:
 *   • tool-call parts → a collapsible "Working" trace, one line per step
 *   • the trailing text → the final answer, streamed on its own
 *
 * "Still working" is carried entirely by the shimmer on the *last* step: it keeps
 * sweeping whenever the turn is running, including the common case where a tool
 * call has finished and we're just waiting on the model to say what's next. When
 * the turn completes the trace collapses to "Worked for Ns" and the answer is
 * revealed. Plain replies with no tool calls remain buffered while running,
 * then render immediately once the turn settles.
 */

const formatDuration = (seconds: number): string => {
  const totalSeconds = Math.max(1, Math.round(seconds));
  if (totalSeconds < 60) return `${totalSeconds}s`;
  const m = Math.floor(totalSeconds / 60);
  const s = totalSeconds % 60;
  return `${m}m ${s}s`;
};

/** useLayoutEffect on the client, useEffect on the server (dodges the SSR warning). */
const useIsomorphicLayoutEffect =
  typeof window !== "undefined" ? useLayoutEffect : useEffect;

/** Matches the header collapse (duration-300 ease-out). */
const WINDOW_ANIM_MS = 300;

/**
 * Whenever the trace is open — live or after completion — it is capped to this
 * height so a long run of steps doesn't march down the whole screen. Newest
 * steps stay pinned at the bottom; older ones remain available by scrolling the
 * trace under edge fades (see `.aui-working-trace-edge-fade`). Sized to show
 * ~5 full steps with the adjacent rows dissolving at the edges. "Show all"
 * remains available when an uncapped overview is more useful.
 */
const WORKING_WINDOW_PX = 260;

/**
 * One tool call of the mother's own trace. The presentation lives in
 * `ToolStepRow` (shared with a delegated agent's child steps); this wrapper
 * only unpacks the transcript part.
 */
const WorkingStep: FC<{
  tool: ToolCallMessagePart;
  relatedResults?: unknown[];
  active: boolean;
  animate: boolean;
  live: boolean;
}> = ({ tool, relatedResults, active, animate, live }) => {
  const done = tool.result !== undefined;
  const argsText =
    tool.argsText && tool.argsText !== "undefined" ? tool.argsText : undefined;

  return (
    <ToolStepRow
      interpretation={interpretToolStep({
        toolName: tool.toolName,
        argsText,
        result: tool.result,
        relatedResults,
      })}
      argsText={argsText}
      detailText={done ? toDetailString(tool.result) : undefined}
      done={done}
      active={active}
      animate={animate}
      animateUpdates={live}
    />
  );
};

/**
 * One rendered row of the trace: a tool step, a run of interstitial talk, or a
 * delegated agent (whose own steps hang off it).
 */
type TraceItem =
  | { kind: "tool"; tool: ToolCallMessagePart; key: string }
  | { kind: "note"; text: string; key: string }
  | {
      kind: "agent";
      agentId: string;
      /** Present once the mother's `task` part has landed in the transcript. */
      tool?: ToolCallMessagePart;
      /** Present while the live sidecar knows about the run. */
      run?: TaskRunState;
      /** Appearance order within the turn — picks the row's identity color. */
      order: number;
      key: string;
    };

/** Child steps an agent row contributes to the header/pill step count. */
const childStepCount = (item: TraceItem): number =>
  item.kind === "agent" ? agentStepCount(item.run) : 0;

const taskResultAgentIds = (result: unknown): string[] => {
  if (!result || typeof result !== "object") return [];
  const record = result as Record<string, unknown>;
  const candidates: unknown[] = [record.agent_id];
  if (record.error && typeof record.error === "object") {
    candidates.push((record.error as Record<string, unknown>).agent_id);
  }
  if (Array.isArray(record.results)) {
    for (const item of record.results) {
      if (!item || typeof item !== "object") continue;
      const child = item as Record<string, unknown>;
      candidates.push(child.agent_id);
      if (child.error && typeof child.error === "object") {
        candidates.push((child.error as Record<string, unknown>).agent_id);
      }
    }
  }
  return [
    ...new Set(
      candidates.filter(
        (id): id is string => typeof id === "string" && id.length > 0,
      ),
    ),
  ];
};

const ThinkingStatusGlyph: FC = () => (
  <span
    aria-hidden="true"
    className="aui-thinking-glyph text-aomi-accent flex size-4 shrink-0 items-center justify-center"
  >
    <LightbulbIcon className="aui-thinking-bulb size-[15px] stroke-[1.8]" />
  </span>
);

const WorkingStatusGlyph: FC = () => (
  <span
    aria-hidden="true"
    className="aui-working-glyph text-aomi-accent flex size-4 shrink-0 items-center justify-center"
  >
    <CogIcon className="aui-working-cog size-[15px] stroke-[1.8]" />
  </span>
);

const WORKING_STATUS_TEXT_CLASS = "text-[13px] font-medium leading-none";
const WORKING_COLLAPSED_CHIP_CLASS =
  "border-aomi-border bg-aomi-surface h-8 w-fit rounded-full pl-3 pr-4";

type WorkingTraceOutcome = "running" | "complete" | "failed" | "interrupted";

export const WorkingTrace: FC<{
  running: boolean;
  outcome?: WorkingTraceOutcome;
  items: TraceItem[];
  revealed: number;
  /** Final-answer playback has begun, so the open trace may fold away. */
  collapseReady?: boolean;
  /**
   * When the turn actually started, if known. The card can mount long after
   * the work began (the transcript part for a delegation only lands at the
   * end), so mount time alone under-reports "Orchestrated for Ns" badly.
   */
  startedAtMs?: number;
}> = ({
  running,
  outcome = running ? "running" : "complete",
  items,
  revealed,
  collapseReady = true,
  startedAtMs,
}) => {
  const [open, setOpen] = useState(running);
  const [expanded, setExpanded] = useState(false);
  const [overflowing, setOverflowing] = useState(false);
  const [hasContentBelow, setHasContentBelow] = useState(false);
  // True only while the expand/collapse height tween is in flight; keeps the
  // viewport clipped and suppresses the edge fades so the animation reads cleanly.
  const [animating, setAnimating] = useState(false);
  const viewportRef = useRef<HTMLDivElement>(null);
  // The inner content's natural height, read for overflow detection and the
  // expand/collapse tween. Measuring the body keeps the result stable while the
  // viewport is capped or its max-height animation is in flight.
  const bodyRef = useRef<HTMLDivElement>(null);
  // Live traces follow new steps while the reader is at the bottom. Scrolling up
  // opts out until they return to the newest step, so a tool update never yanks
  // an older row out from under the pointer.
  const followLatestRef = useRef(true);
  const prevOpen = useRef(open);
  const prevWindowed = useRef(!expanded);
  const prevExpanded = useRef(expanded);
  const animRef = useRef<Animation | null>(null);
  const [elapsed, setElapsed] = useState<number | null>(null);
  const wasRunning = useRef(running);
  const startedAt = useRef<number>(startedAtMs ?? Date.now());
  // An earlier anchor can arrive after mount (e.g. the first task_started
  // event lands a beat later); only ever move the start backwards.
  if (startedAtMs !== undefined && startedAtMs < startedAt.current) {
    startedAt.current = startedAtMs;
  }

  // How many items have already played their entrance. Survives the body's
  // collapse/remount (this component stays mounted), so an item only animates
  // the first time it's revealed — reopening a finished trace shows it static.
  const animatedCount = useRef(0);
  useEffect(() => {
    if (revealed > animatedCount.current) animatedCount.current = revealed;
  }, [revealed]);

  // The trace has fully caught up once every queued item has been revealed.
  const fullyRevealed = !running && revealed >= items.length;

  // A delegated agent remains one top-level trace item while its nested step
  // stream grows. Track that growth separately: `revealed` does not change for
  // those updates, but the viewport still needs to follow the newest child step.
  const revealedChildStepCount = items.reduce(
    (total, item, index) =>
      index < revealed && item.kind === "agent"
        ? total + (item.run?.steps.length ?? 0)
        : total,
    0,
  );

  // Cap the open trace to a scrolling window — live and after completion alike:
  // the newest steps stay pinned at the bottom and older ones remain wheel/touch/
  // keyboard-scrollable under edge fades instead of marching down the page.
  // Expanding ("Show all") still lifts the cap. The fades only engage once
  // content actually overflows, so a short trace is never faded.
  const windowed = !expanded;
  useEffect(() => {
    const body = bodyRef.current;
    if (!body || !windowed) {
      setOverflowing(false);
      return;
    }
    // Compare the full content height to the cap directly, so the reading stays
    // stable while the expand/collapse height animation is mid-flight — otherwise
    // the "Show all" control would flicker out.
    setOverflowing(body.offsetHeight - WORKING_WINDOW_PX > 24);
  }, [windowed, revealed, revealedChildStepCount, open]);

  const handleViewportScroll = () => {
    const viewport = viewportRef.current;
    if (!viewport) return;
    const distanceFromBottom =
      viewport.scrollHeight - viewport.clientHeight - viewport.scrollTop;
    followLatestRef.current = distanceFromBottom <= 8;
    setHasContentBelow(distanceFromBottom > 8);
  };

  // Animate the expand/collapse of the window height (cap ⇄ full content),
  // mirroring the header's collapse feel. Plain CSS can't transition to/from the
  // uncapped `auto` height, so we drive it with the Web Animations API: measure
  // the natural height and tween `max-height` between the cap and full. WAAP
  // overrides the declarative style while playing and reverts to it on finish —
  // which already matches the tween's end value, so it settles seamlessly. Runs
  // in a layout effect (before paint, so the first frame is already clipped) and
  // only when `expanded` actually flips — not on mount, streaming re-renders, or
  // under reduced motion.
  useIsomorphicLayoutEffect(() => {
    if (prevExpanded.current === expanded) return;
    prevExpanded.current = expanded;
    const viewport = viewportRef.current;
    const body = bodyRef.current;
    if (!viewport || !body || prefersReducedMotion()) return;
    const cap = WORKING_WINDOW_PX;
    const full = body.offsetHeight;
    const from = expanded ? cap : full;
    const to = expanded ? full : cap;
    animRef.current?.cancel();
    setAnimating(true);
    const anim = viewport.animate(
      [{ maxHeight: `${from}px` }, { maxHeight: `${to}px` }],
      { duration: WINDOW_ANIM_MS, easing: "ease-out" },
    );
    animRef.current = anim;
    const settle = () => {
      if (animRef.current !== anim) return;
      animRef.current = null;
      setAnimating(false);
    };
    anim.onfinish = settle;
    anim.oncancel = settle;
  }, [expanded]);

  // Start/restart a capped trace at its newest step. While it stays open, only
  // follow streamed additions when the reader has not scrolled away from the
  // bottom. This also restores the recent-step view after "Collapse to recent".
  useIsomorphicLayoutEffect(() => {
    const viewport = viewportRef.current;
    const reopened = open && !prevOpen.current;
    const collapsedToWindow = windowed && !prevWindowed.current;

    if (reopened || collapsedToWindow) followLatestRef.current = true;
    prevOpen.current = open;
    prevWindowed.current = windowed;

    if (!viewport || !open || !windowed || animating) return;
    if (followLatestRef.current) {
      viewport.scrollTop = viewport.scrollHeight;
      setHasContentBelow(false);
    }
  }, [animating, open, revealed, revealedChildStepCount, windowed]);

  useEffect(() => () => animRef.current?.cancel(), []);

  useEffect(() => {
    if (wasRunning.current && !running) {
      // turn just finished: freeze the timer (collapse waits for full reveal)
      setElapsed((Date.now() - startedAt.current) / 1000);
    }
    wasRunning.current = running;
  }, [running]);

  // Auto-collapse only once final-answer playback has actually begun. An
  // awaiting Action temporarily marks the assistant message complete, but the
  // trace must stay open through approval and the resumed model turn.
  useEffect(() => {
    if (!fullyRevealed || !collapseReady) return;
    const timer = setTimeout(() => setOpen(false), 500);
    return () => clearTimeout(timer);
  }, [collapseReady, fullyRevealed]);

  const elapsedLabel =
    elapsed != null ? ` after ${formatDuration(elapsed)}` : "";
  const label =
    outcome === "running"
      ? "Working"
      : outcome === "complete"
        ? elapsed != null
          ? `Worked for ${formatDuration(elapsed)}`
          : "Worked it out"
        : `Stopped${elapsedLabel}`;

  // Keep the status treatment continuous from Thinking into Working. The newest
  // revealed step retains its contextual shimmer while the header consistently
  // communicates that the overall turn is still live.
  const activeIndex = running ? revealed - 1 : -1;
  const headerClass = running ? "aui-working-shimmer" : "text-aomi-fg";

  const visibleItems = items.slice(0, revealed);

  // Step count rule: every shown row counts as one step, and a delegated agent
  // row additionally contributes its child steps (its reported `stepCount`, or
  // the steps actually observed). So a turn of 3 mother steps around one agent
  // that ran 5 child steps reads "9 steps" — the agent row itself is a step.
  const stepCount = visibleItems.reduce(
    (total, item) => total + 1 + childStepCount(item),
    0,
  );

  return (
    // Keep one stable column in both states so the body has a real 0fr ⇄ 1fr
    // path to animate through. The closed shell is transparent and only its
    // compact header chip remains visible.
    <div
      className={cn(
        "aui-working-trace animate-in fade-in-0 zoom-in-95 slide-in-from-bottom-1 mb-3 flex w-full origin-top-left flex-col overflow-hidden rounded-xl border transition-[border-color,background-color,box-shadow] duration-300 ease-out motion-reduce:animate-none motion-reduce:transition-none",
        open
          ? "border-aomi-border/70 bg-aomi-surface/25 shadow-[0_6px_20px_rgba(0,0,0,0.025)]"
          : "border-transparent bg-transparent shadow-none",
      )}
    >
      <button
        type="button"
        onClick={() => setOpen((o) => !o)}
        aria-expanded={open}
        className={cn(
          "aui-working-trace-header flex items-center gap-2 border text-left text-sm transition-[height,padding,border-radius,border-color,background-color] duration-300 ease-out motion-reduce:transition-none",
          open
            ? "bg-aomi-surface/65 h-10 w-full self-stretch rounded-[11px] border-transparent px-3.5"
            : cn(
                WORKING_COLLAPSED_CHIP_CLASS,
                "hover:border-aomi-muted/40 self-start",
              ),
        )}
      >
        {outcome === "running" ? (
          <WorkingStatusGlyph />
        ) : outcome === "failed" ? (
          <span className="flex size-4 shrink-0 items-center justify-center">
            <XIcon className="text-aomi-danger size-3.5" />
          </span>
        ) : outcome === "interrupted" ? (
          <span className="text-aomi-muted flex size-4 shrink-0 items-center justify-center">
            <MoreHorizontalIcon className="size-3.5" />
          </span>
        ) : (
          <span className="flex size-4 shrink-0 items-center justify-center">
            <CheckIcon className="text-aomi-success size-3.5" />
          </span>
        )}
        <span className={cn(WORKING_STATUS_TEXT_CLASS, headerClass)}>
          {label}
        </span>
        {stepCount > 0 ? (
          <span className="text-aomi-muted inline-flex items-center text-[11px] font-normal tabular-nums leading-none">
            {stepCount} {stepCount === 1 ? "step" : "steps"}
          </span>
        ) : null}
        {open && <span className="flex-1" />}
        <ChevronDownIcon
          className={cn(
            "text-aomi-muted size-3.5 shrink-0 transition-transform duration-300 ease-out motion-reduce:transition-none",
            open && "rotate-180",
          )}
        />
      </button>

      {/* Collapse animates the grid row from 1fr→0fr (plus a fade) instead of
          snapping shut. The body stays mounted so items never remount. */}
      <div
        aria-hidden={!open}
        inert={!open}
        className={cn(
          "grid w-full transition-[grid-template-rows,opacity] duration-300 ease-out motion-reduce:transition-none",
          open ? "grid-rows-[1fr] opacity-100" : "grid-rows-[0fr] opacity-0",
        )}
      >
        <div className="min-h-0 overflow-hidden">
          <div className="border-aomi-border/60 bg-aomi-bg/15 relative border-t">
            {windowed && overflowing && !animating && (
              <>
                <span
                  aria-hidden="true"
                  className="aui-working-trace-edge-fade-top pointer-events-none absolute inset-x-0 top-0 z-20 h-16"
                />
                {hasContentBelow && (
                  <span
                    aria-hidden="true"
                    className="aui-working-trace-edge-fade-bottom pointer-events-none absolute inset-x-0 bottom-0 z-20 h-16"
                  />
                )}
              </>
            )}
            <div
              ref={viewportRef}
              onScroll={handleViewportScroll}
              tabIndex={windowed && overflowing ? 0 : undefined}
              aria-label={
                windowed && overflowing ? "Working trace steps" : undefined
              }
              className={cn(
                "aui-working-trace-viewport",
                windowed && !animating && "overflow-y-auto",
                animating && "overflow-hidden",
                windowed &&
                  overflowing &&
                  !animating &&
                  "aui-working-trace-scroll",
              )}
              style={{ maxHeight: windowed ? WORKING_WINDOW_PX : undefined }}
            >
              <div
                ref={bodyRef}
                className="aui-working-trace-body relative isolate flex flex-col gap-1 px-3.5 pb-3.5 pt-3 text-sm"
              >
                {visibleItems.map((item, i) => {
                  const animate = running && i >= animatedCount.current;
                  if (item.kind === "tool") {
                    return (
                      <WorkingStep
                        key={item.key}
                        tool={item.tool}
                        relatedResults={visibleItems
                          .slice(0, i)
                          .flatMap((previous) =>
                            previous.kind === "tool"
                              ? [previous.tool.result]
                              : [],
                          )}
                        active={i === activeIndex}
                        animate={animate}
                        live={running}
                      />
                    );
                  }
                  if (item.kind === "agent") {
                    return (
                      <WorkingAgent
                        key={item.key}
                        agentId={item.agentId}
                        run={item.run}
                        tool={item.tool}
                        order={item.order}
                        // A live agent row owns the trace's single live signal:
                        // it re-homes the shimmer onto its newest child (open)
                        // or onto its own summary line (folded).
                        active={i === activeIndex}
                        animate={animate}
                      />
                    );
                  }
                  return (
                    <WorkingNote
                      key={item.key}
                      text={item.text}
                      animate={animate}
                    />
                  );
                })}
              </div>
            </div>
          </div>
          {/* Below the window: while it's hiding older steps, offer a way to lift
              the cap; while expanded, offer the way back to just the recent steps.
              Shown live and after completion — the window persists either way. */}
          {((windowed && overflowing) || expanded) && (
            <button
              type="button"
              onClick={() => setExpanded((e) => !e)}
              className="aui-working-trace-more text-aomi-muted hover:text-aomi-fg flex items-center gap-1.5 px-3.5 pb-3 text-xs"
            >
              <MoreHorizontalIcon className="size-3.5 shrink-0" />
              {expanded
                ? "Collapse to recent steps"
                : `Show all ${stepCount} steps`}
            </button>
          )}
        </div>
      </div>
    </div>
  );
};

export const MinimalWorkingTrace: FC = () => (
  <div
    role="status"
    aria-label="Aomi is thinking"
    className={cn(
      "aui-working-trace-start animate-in fade-in-0 zoom-in-95 slide-in-from-bottom-1 mb-3 flex origin-top-left items-center gap-2 border duration-300 ease-out motion-reduce:animate-none",
      WORKING_COLLAPSED_CHIP_CLASS,
    )}
  >
    <ThinkingStatusGlyph />
    <span className={cn(WORKING_STATUS_TEXT_CLASS, "aui-working-shimmer")}>
      Thinking
    </span>
  </div>
);

const collectText = (parts: TextMessagePart[]): string =>
  parts
    .map((part) => part.text)
    .join("\n\n")
    .trim();

/**
 * The final answer is deliberately buffered while tools are running because a
 * text part is provisional until the last tool call lands. Once the turn has
 * settled, reveal that buffered answer with a lightweight synthetic stream so
 * it hands off naturally from the trace instead of appearing in one paint.
 *
 * The cadence scales with answer length and tops out at a few seconds: short
 * answers still feel typed, while long reports do not make the reader wait.
 */
const ANSWER_STREAM_TICK_MS = 20;
const ANSWER_STREAM_MS_PER_CHARACTER = 5.5;
const ANSWER_STREAM_MIN_MS = 180;
const ANSWER_STREAM_MAX_MS = 1400;

const answerStreamChunkSize = (length: number): number => {
  const duration = Math.min(
    ANSWER_STREAM_MAX_MS,
    Math.max(ANSWER_STREAM_MIN_MS, length * ANSWER_STREAM_MS_PER_CHARACTER),
  );
  return Math.max(1, Math.ceil(length / (duration / ANSWER_STREAM_TICK_MS)));
};

const useProgressiveAnswer = (
  text: string,
  animate: boolean,
): { text: string; streaming: boolean } => {
  const reduced = prefersReducedMotion();
  const shouldAnimate = animate && !reduced;
  const [visibleLength, setVisibleLength] = useState(() =>
    shouldAnimate ? 0 : text.length,
  );

  useEffect(() => {
    if (!shouldAnimate) {
      setVisibleLength(text.length);
      return;
    }
    // Content is append-only in normal operation. The clamp also handles a
    // reconciliation replacing it with a shorter canonical answer.
    setVisibleLength((current) => Math.min(current, text.length));
  }, [shouldAnimate, text.length]);

  useEffect(() => {
    if (!shouldAnimate || visibleLength >= text.length) return;
    const chunk = answerStreamChunkSize(text.length);
    const timer = setTimeout(
      () =>
        setVisibleLength((current) => Math.min(text.length, current + chunk)),
      ANSWER_STREAM_TICK_MS,
    );
    return () => clearTimeout(timer);
  }, [shouldAnimate, text.length, visibleLength]);

  return {
    text: text.slice(0, visibleLength),
    streaming: shouldAnimate && visibleLength < text.length,
  };
};

const RenderedText: FC<{ text: string }> = ({ text }) => {
  return (
    <TextMessagePartProvider text={text}>
      <MarkdownText />
    </TextMessagePartProvider>
  );
};

export const ProgressiveRenderedText: FC<{
  text: string;
  animate: boolean;
}> = ({ text, animate }) => {
  const progressive = useProgressiveAnswer(text, animate);
  return (
    <div aria-busy={progressive.streaming || undefined}>
      <RenderedText text={progressive.text} />
    </div>
  );
};

/**
 * Reconcile the ordered transcript with the live delegation sidecar.
 *
 * A task exists in the sidecar before its transcript tool part arrives. Once
 * that part does arrive, it replaces the synthetic row at the transcript's
 * chronological position instead of being appended again at the bottom. This
 * matters when a failed child is followed by successful parent work: the
 * failure remains useful history without looking like the final active step.
 */
export const buildTraceItems = (
  content: readonly (TextMessagePart | ToolCallMessagePart)[],
  liveDelegations: readonly TaskRunState[],
): TraceItem[] => {
  const items: TraceItem[] = [];
  const runsByAgentId = new Map(
    liveDelegations.map((run) => [run.agentId, run] as const),
  );
  const taskParts = content.filter(
    (part): part is ToolCallMessagePart =>
      part.type === "tool-call" && part.toolName === "task",
  );
  const occurrences = new Map<string, number>();
  for (const part of taskParts) {
    for (const agentId of taskResultAgentIds(part.result)) {
      occurrences.set(agentId, (occurrences.get(agentId) ?? 0) + 1);
    }
  }
  const consumedRuns = new Set<TaskRunState>();
  const invocationKey = (callId: string, agentId: string) =>
    `agent-${JSON.stringify([callId, agentId])}`;
  let agentOrder = 0;

  content.forEach((part, i) => {
    if (part.type === "tool-call") {
      if (part.toolName === "task") {
        const resultAgentIds = taskResultAgentIds(part.result);
        const callId = part.toolCallId ?? `task-${i}`;
        // Batch children use <tool call>:<one-based index> on the wire.
        const matchedRuns = liveDelegations.filter(
          (run) =>
            run.callId === callId ||
            (run.callId.startsWith(`${callId}:`) &&
              /^\d+$/.test(run.callId.slice(callId.length + 1))),
        );
        const agentIds = [
          ...new Set([
            ...resultAgentIds,
            ...matchedRuns.map((run) => run.agentId),
          ]),
        ];
        for (const agentId of agentIds.length ? agentIds : [callId]) {
          const exactRun = matchedRuns.find((run) => run.agentId === agentId);
          // Legacy inline messages lack canonical call identity. Only join an
          // unambiguous child once; a continuation must not rewrite history.
          const legacyRun =
            callId.startsWith("inline:") && occurrences.get(agentId) === 1
              ? runsByAgentId.get(agentId)
              : undefined;
          const run = exactRun ?? legacyRun;
          if (run) consumedRuns.add(run);
          items.push({
            kind: "agent",
            agentId,
            run,
            tool: part,
            order: agentOrder++,
            key: invocationKey(run?.callId ?? callId, agentId),
          });
        }
        return;
      }

      items.push({
        kind: "tool",
        tool: part,
        key: part.toolCallId ?? `tool-${i}`,
      });
      return;
    }

    if (part.text.trim().length === 0) return;
    const prev = items[items.length - 1];
    if (prev?.kind === "note") prev.text += `\n\n${part.text}`;
    else items.push({ kind: "note", text: part.text, key: `note-${i}` });
  });

  for (const run of liveDelegations) {
    if (consumedRuns.has(run)) continue;
    items.push({
      kind: "agent",
      agentId: run.agentId,
      run,
      order: agentOrder++,
      key: invocationKey(run.callId, run.agentId),
    });
  }

  return items;
};

/**
 * Drop-in replacement for `<MessagePrimitive.Parts>` in an assistant message.
 *
 * A merged turn is one ordered `content` array: interstitial talk (`text`) and
 * tool calls, then the final answer (`text`). We split at the LAST tool call —
 * everything up to and including it is the Working trace (tool steps + muted
 * interstitial notes, in order); the trailing `text` run is the final answer,
 * buffered out of view until the turn finishes so only it streams out below.
 * A plain reply with no tool calls remains buffered while running, then renders
 * directly once it is known to be the final answer.
 *
 * Delegations are the one row that does not come from the transcript alone: a
 * running child has no `task` part yet, so its row is rendered synthetically
 * from the `taskRuns` sidecar and hands over to the transcript part (same key,
 * same row) once that lands. See `WorkingAgent`.
 */
export const AssistantTurnParts: FC = () => {
  const content = useMessage((s) => s.content);
  const running = useMessage((s) => s.status?.type === "running");
  const isLast = useMessage((s) => s.isLast);
  const runtime = useOptionalAomiRuntime();
  const taskRuns = useThreadTaskRuns("turn");
  // Only animate a turn observed live in this component. Completed messages
  // restored from history render immediately instead of replaying the effect.
  const witnessedRunning = useRef(running);
  if (running) witnessedRunning.current = true;

  const lastToolIndex = content.reduce(
    (last, part, i) => (part.type === "tool-call" ? i : last),
    -1,
  );

  // The activity rail projects the whole thread, while a message trace only
  // consumes the current turn's sidecar. History renders from its transcript.
  const liveDelegations = isLast
    ? Object.values(taskRuns).sort((a, b) => a.startedAt - b.startedAt)
    : [];

  // Where the trace ends and the final answer begins. Normally the last tool
  // call — but a delegation that has not landed in the transcript yet has no
  // tool part at all, so a turn that is *only* a live delegation still gets a
  // trace (its talk becomes notes; the answer is buffered while running).
  const traceEnd =
    lastToolIndex >= 0
      ? lastToolIndex + 1
      : liveDelegations.length > 0
        ? content.length
        : 0;

  const answerText = collectText(
    content
      .slice(traceEnd)
      .filter((part): part is TextMessagePart => part.type === "text"),
  );

  const traceContent = content
    .slice(0, traceEnd)
    .filter(
      (part): part is TextMessagePart | ToolCallMessagePart =>
        part.type === "text" || part.type === "tool-call",
    );
  const items = buildTraceItems(traceContent, liveDelegations);

  // Awaiting an approval is a pause in the same turn, not completion. Keep the
  // trace visibly live until a real final answer exists and can begin its
  // synthetic stream. This also covers the short resume gap after approve or
  // reject, when polling has restarted but the next model event has not landed.
  const terminal =
    runtime?.turnState === "complete" ||
    runtime?.turnState === "interrupted" ||
    runtime?.turnState === "failed";
  const awaitingContinuation =
    !terminal &&
    isLast &&
    items.length > 0 &&
    (runtime?.turnState === "awaiting_action" ||
      runtime?.turnState === "processing" ||
      (witnessedRunning.current && answerText.length === 0));
  const traceLive = !terminal && (running || awaitingContinuation);
  const outcome: WorkingTraceOutcome = traceLive
    ? "running"
    : isLast && runtime?.turnState === "failed"
      ? "failed"
      : isLast && runtime?.turnState === "interrupted"
        ? "interrupted"
        : "complete";
  // A durable backend notice is projected as the following assistant message,
  // making this turn no longer last. While none exists, keep a failed turn from
  // ending in partial prose (or a tool trace) with no explanation.
  const showFailureFallback = outcome === "failed";

  // Transcript state is never delayed behind presentation. Rows enter the DOM
  // immediately; their bounded CSS entrance and chip cascade provide motion
  // without falling behind the activity rail during a batch.
  const revealed = items.length;

  // When the work actually began, for the header's "Orchestrated for Ns".
  // Anchored to the earliest signal we have: the moment this turn was first
  // seen running, or the earliest delegation's client-clock start — whichever
  // is older. Mount time alone lies when the trace mounts late (a delegating
  // turn's transcript part only lands at the very end).
  const turnStartRef = useRef<number | null>(running ? Date.now() : null);
  if (running && turnStartRef.current === null) {
    turnStartRef.current = Date.now();
  }
  const earliestRunStart = items.reduce<number | null>(
    (earliest, item) =>
      item.kind === "agent" && item.run
        ? Math.min(earliest ?? item.run.startedAt, item.run.startedAt)
        : earliest,
    null,
  );
  const startedAtMs =
    turnStartRef.current !== null && earliestRunStart !== null
      ? Math.min(turnStartRef.current, earliestRunStart)
      : (turnStartRef.current ?? earliestRunStart ?? undefined);

  if (items.length === 0) {
    // Before the first tool call, text is provisional: a later tool can move it
    // into the Working trace. Keep it buffered until the turn settles.
    if (running) {
      return runtime?.turnState === "processing" ? (
        <MinimalWorkingTrace />
      ) : null;
    }

    return answerText.length > 0 || showFailureFallback ? (
      <>
        {answerText.length > 0 && (
          <ProgressiveRenderedText
            text={answerText}
            animate={witnessedRunning.current}
          />
        )}
        {showFailureFallback && <TurnFailureFallback />}
      </>
    ) : null;
  }

  // Every trace item is already mounted, so presentation never gates the answer.
  const answerReady = !traceLive && revealed >= items.length;

  return (
    <>
      <WorkingTrace
        running={traceLive}
        outcome={outcome}
        items={items}
        revealed={revealed}
        collapseReady={answerText.length > 0}
        startedAtMs={startedAtMs}
      />
      {answerReady && answerText.length > 0 && (
        <div className="aui-working-answer">
          <ProgressiveRenderedText
            text={answerText}
            animate={witnessedRunning.current}
          />
        </div>
      )}
      {answerReady && showFailureFallback && <TurnFailureFallback />}
    </>
  );
};

const TurnFailureFallback: FC = () => (
  <p className="text-aomi-danger mt-2 text-sm leading-5" role="status">
    This run stopped before it could finish.
  </p>
);

"use client";

import { type FC, useEffect, useRef, useState } from "react";
import { TextMessagePartProvider } from "@assistant-ui/react";
import { CheckIcon, ChevronRightIcon, XIcon } from "lucide-react";

import { cn } from "@aomi-labs/react";
import { MarkdownText } from "@/components/assistant-ui/markdown-text";
import type {
  InterpretedToolStep,
  ToolChip,
} from "@/components/assistant-ui/tool-interpreter";

/**
 * The primitive rows shared by the mother trace (`working-trace.tsx`) and a
 * delegated agent's subtree (`working-agent.tsx`).
 *
 * They live here rather than in `working-trace.tsx` because the trace imports
 * `WorkingAgent` and the agent renders these rows — keeping them in a leaf
 * module avoids an import cycle between the two. Nothing in here knows about
 * transcript parts or task runs: callers hand over an already-interpreted step.
 */

export const prefersReducedMotion = (): boolean =>
  typeof window !== "undefined" &&
  typeof window.matchMedia === "function" &&
  window.matchMedia("(prefers-reduced-motion: reduce)").matches;

export const toDetailString = (result: unknown): string =>
  typeof result === "string" ? result : JSON.stringify(result, null, 2);

/**
 * The expanded args/result box. Capped to ~20 lines (`max-h-[26rem]`) and made
 * scrollable beyond that, so a long tool payload (e.g. a full transaction dump
 * of raw calldata) scrolls in place instead of marching the trace — and the
 * answer below it — far down the page.
 */
export const DETAIL_BOX_CLASS =
  "border-aomi-border bg-aomi-surface text-aomi-muted max-h-[26rem] overflow-auto whitespace-pre-wrap break-words rounded-md border p-2 font-mono text-xs leading-relaxed";

const MAX_VISIBLE_CHIPS = 4;

/** Base + per-chip stagger for the left-to-right chip cascade (ms). */
const CHIP_BASE_DELAY_MS = 15;
const CHIP_STEP_DELAY_MS = 25;

export const ToolChipView: FC<{
  chip: ToolChip;
  index: number;
  animate: boolean;
}> = ({ chip, index, animate }) => {
  const Glyph = chip.icon;
  return (
    <span
      className={cn(
        "border-aomi-border/80 bg-aomi-raised text-aomi-muted inline-flex min-w-0 max-w-full items-center gap-1.5 rounded-full border px-2.5 py-1.5 text-[11px] tabular-nums leading-none",
        animate &&
          "animate-in fade-in-0 slide-in-from-bottom-1 fill-mode-both duration-[180ms] motion-reduce:animate-none",
      )}
      style={
        animate
          ? {
              animationDelay: `${CHIP_BASE_DELAY_MS + index * CHIP_STEP_DELAY_MS}ms`,
            }
          : undefined
      }
    >
      {chip.dot ? (
        <span
          className="size-[5px] shrink-0 rounded-full"
          style={{ backgroundColor: chip.dot }}
          aria-hidden="true"
        />
      ) : (
        !Glyph && (
          <span
            className="bg-aomi-accent size-[5px] shrink-0 rounded-full"
            aria-hidden="true"
          />
        )
      )}
      {Glyph && <Glyph className="text-aomi-fg/80 size-3.5 shrink-0" />}
      <span className="truncate">{chip.label}</span>
    </span>
  );
};

/**
 * One interpreted tool call, as a flat row: marker · title · chips, with an
 * optional click-to-open `<pre>` detail holding the raw args/result.
 *
 * `done` drives the check/X marker (the interpreted icon shows until then) and
 * `active` is the single live signal — the title shimmers while it is set.
 */
export const ToolStepRow: FC<{
  interpretation: InterpretedToolStep;
  argsText?: string;
  detailText?: string;
  done: boolean;
  active: boolean;
  animate: boolean;
  animateUpdates?: boolean;
  className?: string;
}> = ({
  interpretation,
  argsText,
  detailText,
  done,
  active,
  animate,
  animateUpdates = false,
  className,
}) => {
  const [open, setOpen] = useState(false);
  const hasDetail = detailText !== undefined || argsText !== undefined;
  const Icon = interpretation.icon;
  const shownChips =
    interpretation.chips.length > MAX_VISIBLE_CHIPS
      ? interpretation.chips.slice(0, MAX_VISIBLE_CHIPS)
      : interpretation.chips;
  const overflow = interpretation.chips.length - shownChips.length;
  const chipKeys = interpretation.chips.map((chip) => chip.label.toLowerCase());
  const seenChipKeys = useRef(new Set(animate ? [] : chipKeys));
  const hasNewOverflowChip = chipKeys
    .slice(shownChips.length)
    .some((key) => !seenChipKeys.current.has(key));
  useEffect(() => {
    chipKeys.forEach((key) => seenChipKeys.current.add(key));
  });

  return (
    <div
      className={cn(
        "aui-working-step",
        animate &&
          "animate-in fade-in-0 slide-in-from-bottom-1 duration-300 motion-reduce:animate-none",
        className,
      )}
    >
      <button
        type="button"
        disabled={!hasDetail}
        onClick={() => setOpen((o) => !o)}
        className="aui-working-step-header group/step flex w-full items-center gap-2.5 py-1 text-left disabled:cursor-default"
      >
        <span className="relative flex size-4 shrink-0 items-center justify-center">
          {done && !active ? (
            interpretation.failed ? (
              <XIcon className="text-aomi-danger size-3.5" />
            ) : (
              <CheckIcon className="text-aomi-success size-3.5" />
            )
          ) : (
            <Icon className="text-aomi-muted size-3.5" />
          )}
        </span>
        <span
          className={cn(
            "flex-1 truncate text-[13px] font-medium",
            active ? "aui-working-shimmer" : "text-aomi-fg",
          )}
        >
          {interpretation.title}
        </span>
        {/* Detail affordance stays quiet until the row is hovered (or open). */}
        {hasDetail && (
          <ChevronRightIcon
            className={cn(
              "text-aomi-muted/60 size-3 shrink-0 transition-[transform,opacity]",
              open
                ? "rotate-90 opacity-100"
                : "opacity-0 group-hover/step:opacity-100",
            )}
          />
        )}
      </button>

      {interpretation.chips.length > 0 && (
        <div className="aui-working-step-chips mb-1 ml-[26px] mt-1.5 flex max-w-full flex-wrap items-center gap-1.5">
          {shownChips.map((chip, i) => (
            <ToolChipView
              key={chipKeys[i]}
              chip={chip}
              index={i}
              animate={
                animate ||
                (animateUpdates && !seenChipKeys.current.has(chipKeys[i]))
              }
            />
          ))}
          {overflow > 0 && (
            <span
              className={cn(
                "border-aomi-border/80 bg-aomi-raised text-aomi-muted inline-flex items-center rounded-full border px-2.5 py-1.5 text-[11px] leading-none",
                (animate || (animateUpdates && hasNewOverflowChip)) &&
                  "animate-in fade-in-0 slide-in-from-bottom-1 fill-mode-both duration-[180ms] motion-reduce:animate-none",
              )}
              style={
                animate || (animateUpdates && hasNewOverflowChip)
                  ? {
                      animationDelay: `${CHIP_BASE_DELAY_MS + shownChips.length * CHIP_STEP_DELAY_MS}ms`,
                    }
                  : undefined
              }
            >
              +{overflow} more
            </span>
          )}
        </div>
      )}

      {open && hasDetail && (
        <div className="aui-working-step-detail mb-1.5 ml-[26px] mt-4 flex flex-col gap-1.5">
          {argsText && <pre className={DETAIL_BOX_CLASS}>{argsText}</pre>}
          {detailText !== undefined && (
            <pre className={DETAIL_BOX_CLASS}>{detailText}</pre>
          )}
        </div>
      )}
    </div>
  );
};

/**
 * An interstitial line — the model (or a delegated child) talking between tool
 * calls. Rendered as a muted markdown note with a dot marker in the icon column
 * so it lines up with the tool steps on the rail (in order, inside the trace —
 * not in the answer). `active` makes it the single live signal.
 */
export const WorkingNote: FC<{
  text: string;
  animate: boolean;
  active?: boolean;
}> = ({ text, animate, active = false }) => (
  <div
    className={cn(
      "aui-working-note flex items-start gap-2 py-1",
      animate &&
        "animate-in fade-in-0 slide-in-from-bottom-1 duration-300 motion-reduce:animate-none",
    )}
  >
    <span
      className="relative flex h-[19px] w-4 shrink-0 items-center justify-center"
      aria-hidden="true"
    >
      <span className="bg-aomi-muted/60 size-1 rounded-full" />
    </span>
    <div
      className={cn(
        "min-w-0 flex-1 text-[12px] leading-5 [&_p+p]:mt-2 [&_p]:my-0",
        active ? "aui-working-shimmer font-medium" : "text-aomi-muted",
      )}
    >
      <TextMessagePartProvider text={text}>
        <MarkdownText />
      </TextMessagePartProvider>
    </div>
  </div>
);

"use client";

import { type FC, useEffect, useMemo, useRef, useState } from "react";
import type { ToolCallMessagePart } from "@assistant-ui/react";
import {
  BotIcon,
  CheckIcon,
  ChevronRightIcon,
  LayersIcon,
  XIcon,
} from "lucide-react";

import {
  cn,
  type TaskRunState,
  type TaskRunStatus,
  type TaskRunStep,
} from "@aomi-labs/react";
import { interpretToolStep } from "@/components/assistant-ui/tool-interpreter";
import {
  prefersReducedMotion,
  ToolStepRow,
  WorkingNote,
} from "@/components/assistant-ui/working-trace-rows";

/**
 * A delegated child agent, as one row of the working trace.
 *
 * The row is a live surface joined from two sources (see the reconciliation
 * contract in `@aomi-labs/react`'s `TaskRunState`):
 *   • while the child runs there is **no** transcript part — the trace renders
 *     a synthetic row straight off the `taskRuns` sidecar (`run`);
 *   • when the mother's `task` tool-call part lands it renders the same row
 *     (`tool`), with the sidecar still supplying steps and the summary;
 *   • on reload of an older thread there is no sidecar at all, so the row
 *     degrades to what the transcript carries — label from the args, staged
 *     count from the result, no steps ("Phase 0").
 *
 * Behaviour is the decided one: mounts expanded while live, folds itself away
 * ~900ms after it finishes — unless the reader has touched it, in which case it
 * stays exactly as they left it. Children hang off a vertical rail, which is
 * the only marker of whose steps you are reading.
 */

/** Identity colors, cycled by order of appearance within the turn. */
const AGENT_COLORS = ["var(--aomi-accent)", "var(--aomi-pink)"];

/** Beat after completion before an untouched row folds (lets the check land). */
const FOLD_DELAY_MS = 900;

const asRecord = (value: unknown): Record<string, unknown> | undefined =>
  typeof value === "object" && value !== null && !Array.isArray(value)
    ? (value as Record<string, unknown>)
    : undefined;

const asText = (value: unknown): string | undefined =>
  typeof value === "string" && value.trim().length > 0 ? value : undefined;

const asCount = (value: unknown): number | undefined =>
  typeof value === "number" && Number.isFinite(value) ? value : undefined;

const summaryValue = (value: unknown): string | undefined => {
  if (typeof value === "string") return asText(value)?.trim();
  if (typeof value === "number" || typeof value === "boolean") {
    return String(value);
  }
  if (
    Array.isArray(value) &&
    value.length > 0 &&
    value.every(
      (item) =>
        typeof item === "string" ||
        typeof item === "number" ||
        typeof item === "boolean",
    )
  ) {
    return value.map(String).join(", ");
  }
  return undefined;
};

const summaryLabel = (key: string): string => {
  const words = key.replace(/[_-]+/g, " ").trim();
  return words.length > 0 ? `${words[0]!.toUpperCase()}${words.slice(1)}` : key;
};

/**
 * `thread_return.value` may be structured for the parent orchestrator. The
 * task-completion event carries that value as a string, but the compact agent
 * row is a prose surface: preserve ordinary text, extract an explicitly named
 * human summary. When there is no explicit summary field, flatten scalar fields
 * into readable `Input: … · Output: …` prose instead of leaking JSON syntax.
 */
const completionSummary = (value: unknown): string | undefined => {
  const text = asText(value)?.trim();
  if (!text || (!text.startsWith("{") && !text.startsWith("["))) return text;
  try {
    const parsed: unknown = JSON.parse(text);
    if (typeof parsed === "string") return asText(parsed);
    const record = asRecord(parsed);
    const namedSummary =
      asText(record?.summary) ??
      asText(record?.message) ??
      asText(record?.reason);
    if (namedSummary) return namedSummary.trim();
    if (!record) return undefined;
    const facts = Object.entries(record).flatMap(([key, field]) => {
      const rendered = summaryValue(field);
      return rendered ? [`${summaryLabel(key)}: ${rendered}`] : [];
    });
    return facts.length > 0 ? facts.join(" · ") : undefined;
  } catch {
    // TaskCompleted has a small wire budget, so a structured return can arrive
    // clipped into invalid JSON. Its opening delimiter still identifies it as
    // parent-only data; never fall back to rendering that fragment as prose.
    return undefined;
  }
};

/** The `ChildTaskRequest` the mother sent: `{label, app, prompt}`. */
const readArgs = (
  tool: ToolCallMessagePart | undefined,
): Record<string, unknown> | undefined => {
  if (!tool) return undefined;
  const direct = asRecord(tool.args);
  if (direct) return direct;
  if (tool.argsText && tool.argsText !== "undefined") {
    try {
      return asRecord(JSON.parse(tool.argsText));
    } catch {
      return undefined;
    }
  }
  return undefined;
};

const toStatus = (value: unknown): TaskRunStatus | undefined => {
  switch (value) {
    case "running":
    case "completed":
    case "failed":
    case "stalled":
    case "cancelled":
      return value;
    default:
      return undefined;
  }
};

type TerminalNote = { index: number; text: string };

/** Read the child's post-`thread_return` transcript note at its larger budget. */
const terminalReturnNote = (run?: TaskRunState): TerminalNote | undefined => {
  const steps = run?.steps ?? [];
  let returnIndex = -1;
  for (let i = steps.length - 1; i >= 0; i--) {
    const step = steps[i]!;
    if (step.kind === "tool_call" && step.toolName === "thread_return") {
      returnIndex = i;
      break;
    }
  }
  if (returnIndex < 0) return undefined;
  for (let i = steps.length - 1; i > returnIndex; i--) {
    const step = steps[i]!;
    if (step.kind !== "note") continue;
    const text = completionSummary(step.text);
    if (text) return { index: i, text };
  }
  return undefined;
};

/** Best human-readable form of the exact result returned to the mother. */
const agentFinalMessage = (run?: TaskRunState): string | undefined =>
  terminalReturnNote(run)?.text ?? completionSummary(run?.message);

/**
 * The child steps the row actually shows. Protocol `thread_return` stays
 * hidden, but its resulting message is humanized and kept as the final note.
 */
export const visibleAgentSteps = (run?: TaskRunState): TaskRunStep[] => {
  const source = run?.steps ?? [];
  const terminal = terminalReturnNote(run);
  const visible: TaskRunStep[] = [];

  source.forEach((step, index) => {
    if (step.kind === "tool_call") {
      if (step.toolName !== "thread_return") visible.push(step);
      return;
    }
    const text = step.text.trim();
    const structured = text.startsWith("{") || text.startsWith("[");
    if (structured) {
      if (terminal?.index === index) {
        visible.push({ ...step, text: terminal.text });
      }
      return;
    }
    visible.push(step);
  });

  const finalMessage = terminal?.text ?? completionSummary(run?.message);
  const last = visible[visible.length - 1];
  if (
    finalMessage &&
    terminal === undefined &&
    !(last?.kind === "note" && last.text.trim() === finalMessage.trim())
  ) {
    visible.push({
      kind: "note",
      text: finalMessage,
      childSeq: (source[source.length - 1]?.childSeq ?? 0) + 1,
    });
  }
  return visible;
};

/**
 * The step count shown for an agent row — visible tool calls when we have the
 * step stream, the backend's terminal count otherwise (Phase 0). Shared with
 * the trace header so "N steps" always matches what expanding reveals.
 */
export const agentStepCount = (run?: TaskRunState): number => {
  const visible = visibleAgentSteps(run);
  return visible.length > 0
    ? visible.filter((step) => step.kind === "tool_call").length
    : (run?.stepCount ?? 0);
};

const stepKey = (step: TaskRunStep, index: number): string =>
  `${step.kind}-${step.childSeq}-${index}`;

const argsTextOf = (step: Extract<TaskRunStep, { kind: "tool_call" }>) =>
  step.args !== undefined ? JSON.stringify(step.args, null, 2) : undefined;

const titleOf = (step: TaskRunStep): string =>
  step.kind === "note"
    ? step.text
    : interpretToolStep({
        toolName: step.toolName,
        argsText: argsTextOf(step),
        result: step.resultPreview,
      }).title;

const formatCounter = (steps: number, seconds: number | null): string =>
  [
    steps > 0 ? `${steps} step${steps === 1 ? "" : "s"}` : null,
    seconds != null ? `${seconds}s` : null,
  ]
    .filter(Boolean)
    .join(" · ");

/**
 * Elapsed wall-clock since the run started, re-read once a second while it is
 * live. The tick is information rather than decoration, so it runs under
 * `prefers-reduced-motion` too — only the pulsing marker stands still there.
 */
const useElapsedSeconds = (startedAt: number, live: boolean): number => {
  const [now, setNow] = useState(() => Date.now());
  useEffect(() => {
    if (!live) return;
    setNow(Date.now());
    const timer = setInterval(() => setNow(Date.now()), 1000);
    return () => clearInterval(timer);
  }, [live]);
  return Math.max(0, Math.round((now - startedAt) / 1000));
};

export type WorkingAgentProps = {
  agentId: string;
  /** Live sidecar state; absent on a reloaded thread (Phase 0 degradation). */
  run?: TaskRunState;
  /** The mother's `task` tool-call part, once the delegation has landed. */
  tool?: ToolCallMessagePart;
  /** Appearance order within the turn — picks the identity color. */
  order: number;
  /** This row holds the trace's single live signal (it is the newest item). */
  active: boolean;
  /** Play the entrance animation (false for scrollback / reloaded turns). */
  animate: boolean;
};

export const WorkingAgent: FC<WorkingAgentProps> = ({
  agentId,
  run,
  tool,
  order,
  active,
  animate,
}) => {
  const args = readArgs(tool);
  const result = asRecord(tool?.result);

  const status: TaskRunStatus =
    run?.status ?? toStatus(result?.status) ?? (tool ? "completed" : "running");
  const live = status === "running";
  const label = asText(run?.label) ?? asText(args?.label) ?? "agent";
  const steps = useMemo(() => visibleAgentSteps(run), [run]);
  const stepCount = agentStepCount(run);
  const stagedCount = run?.stagedCount ?? asCount(result?.staged_count) ?? 0;
  const startedAt = run?.startedAt ?? 0;

  const [open, setOpen] = useState(live);
  const userToggled = useRef(false);

  // Auto-expand while live, auto-fold a beat after the run goes terminal — but
  // never once the reader has taken the row over.
  useEffect(() => {
    if (userToggled.current) return;
    if (live) {
      setOpen(true);
      return;
    }
    const timer = setTimeout(
      () => {
        if (!userToggled.current) setOpen(false);
      },
      prefersReducedMotion() ? 0 : FOLD_DELAY_MS,
    );
    return () => clearTimeout(timer);
  }, [live]);

  // Children only animate the first time they are shown, so reopening a folded
  // row replays nothing. A row that mounted already-finished never animates.
  const animatedCount = useRef(animate ? 0 : Number.MAX_SAFE_INTEGER);
  useEffect(() => {
    if (!animate) return;
    animatedCount.current = Math.max(animatedCount.current, steps.length);
  }, [animate, steps.length]);

  const elapsedSeconds = useElapsedSeconds(startedAt, live);
  const seconds = live
    ? startedAt > 0
      ? elapsedSeconds
      : null
    : run?.durationMs != null
      ? Math.max(1, Math.round(run.durationMs / 1000))
      : null;

  const latest = steps.length > 0 ? steps[steps.length - 1] : undefined;
  const latestTitle = useMemo(
    () => (latest ? titleOf(latest) : undefined),
    [latest],
  );

  // While live and expanded the children tell the story, so the slot is empty;
  // collapsed, it carries the latest intent as the row's live signal; once the
  // run is done it settles into the child's summary line.
  const completedSummary = agentFinalMessage(run);
  const showsStagedSummary = !live && !completedSummary && stagedCount > 0;
  const summary = live
    ? open
      ? undefined
      : (latestTitle ?? "starting…")
    : (completedSummary ??
      (showsStagedSummary ? `Staged ${stagedCount}` : undefined));
  const summaryShimmers = live && !open && active;

  return (
    <div
      className={cn(
        "aui-working-agent flex flex-col",
        animate &&
          "animate-in fade-in-0 slide-in-from-bottom-1 duration-300 motion-reduce:animate-none",
      )}
      data-agent-id={agentId}
      data-live={live}
      data-open={open}
    >
      <button
        type="button"
        aria-expanded={open}
        onClick={() => {
          userToggled.current = true;
          setOpen((o) => !o);
        }}
        className="aui-working-agent-header group/agent flex w-full items-center gap-2.5 py-1 text-left"
      >
        <span className="relative flex size-4 shrink-0 items-center justify-center">
          {live ? (
            // The robot IS the marker while the child works — same contract as
            // a tool row's icon (identity while running, check when done), and
            // the one glyph that says "a subagent is doing this" at a glance.
            <BotIcon
              className="aui-working-agent-bot size-3.5 animate-pulse motion-reduce:animate-none"
              style={{ color: AGENT_COLORS[order % AGENT_COLORS.length] }}
              aria-hidden="true"
            />
          ) : status === "completed" ? (
            <CheckIcon className="text-aomi-success size-3.5" />
          ) : (
            <XIcon className="text-aomi-danger size-3.5" />
          )}
        </span>
        <span className="aui-working-agent-label text-aomi-fg shrink-0 text-[13px] font-medium">
          {label}
        </span>
        <span
          className={cn(
            "aui-working-agent-summary flex min-w-0 flex-1 items-center gap-1.5 text-[12px]",
            summaryShimmers
              ? "aui-working-shimmer font-medium"
              : "text-aomi-muted",
          )}
        >
          {showsStagedSummary && (
            <LayersIcon
              className="aui-working-agent-staged-icon size-3.5 shrink-0"
              aria-hidden="true"
            />
          )}
          <span className="truncate">{summary}</span>
        </span>
        <span className="aui-working-agent-count text-aomi-muted shrink-0 text-[11px] tabular-nums">
          {formatCounter(stepCount, seconds)}
        </span>
        <ChevronRightIcon
          className={cn(
            "text-aomi-muted/60 size-3 shrink-0 transition-[transform,opacity]",
            open
              ? "rotate-90 opacity-100"
              : "opacity-0 group-hover/agent:opacity-100",
          )}
        />
      </button>

      {/* The subtree animates its height open/closed and stays mounted, so a
          fold never remounts (and never restarts) the child rows. */}
      <div
        className={cn(
          "grid transition-[grid-template-rows,opacity] duration-300 ease-out motion-reduce:transition-none",
          open ? "grid-rows-[1fr] opacity-100" : "grid-rows-[0fr] opacity-0",
        )}
      >
        <div className="min-h-0 overflow-hidden">
          {/* The rail: the only thing marking whose steps these are. */}
          <div className="aui-working-agent-rail border-aomi-border mb-1.5 ml-[7px] mt-0.5 flex flex-col gap-0.5 border-l pl-[17px]">
            {steps.map((step, i) => {
              const newest = i === steps.length - 1;
              const childActive = active && live && open && newest;
              const childAnimate = i >= animatedCount.current;
              if (step.kind === "note") {
                return (
                  <WorkingNote
                    key={stepKey(step, i)}
                    text={step.text}
                    animate={childAnimate}
                    active={childActive}
                  />
                );
              }
              const argsText = argsTextOf(step);
              return (
                <ToolStepRow
                  key={stepKey(step, i)}
                  interpretation={interpretToolStep({
                    toolName: step.toolName,
                    argsText,
                    result: step.resultPreview,
                    relatedResults: steps
                      .slice(0, i)
                      .flatMap((previous) =>
                        previous.kind === "tool_call"
                          ? [previous.resultPreview]
                          : [],
                      ),
                  })}
                  argsText={argsText}
                  detailText={step.resultPreview}
                  done={!newest || !live}
                  active={childActive}
                  animate={childAnimate}
                />
              );
            })}
          </div>
        </div>
      </div>
    </div>
  );
};

import { interpretToolContext } from "./pipeline";
import { unwrapToolStep } from "./unwrap";
import type { InterpretedToolStep, ToolChip, ToolStepInput } from "./types";

export type { InterpretedToolStep, ToolChip, ToolStepInput };

export const interpretToolStep = (input: ToolStepInput): InterpretedToolStep =>
  interpretToolContext(unwrapToolStep(input));

export const resolveToolIcon = (
  topic: string,
  result?: unknown,
): InterpretedToolStep["icon"] =>
  interpretToolStep({ toolName: topic, result }).icon;

export const resolveToolChips = (topic: string, result?: unknown): ToolChip[] =>
  interpretToolStep({ toolName: topic, result }).chips;

import type { LucideIcon } from "lucide-react";
import type { ElementType } from "react";

export type ToolConfidence = "high" | "medium" | "fallback";

export type ToolChip = {
  label: string;
  dot?: string;
  icon?: ElementType;
};

export type InterpretedToolStep = {
  icon: LucideIcon;
  title: string;
  chips: ToolChip[];
  confidence: ToolConfidence;
  rawLabel: string;
  /** The tool reported a failure/error status (drives the red-X step marker). */
  failed: boolean;
};

export type ToolStepInput = {
  toolName: string;
  argsText?: string;
  result?: unknown;
  /** Earlier tool results in the same trace, used to resolve references such
   * as commit `tx_ids` back to the staged transaction's network. */
  relatedResults?: unknown[];
};

export type FactKind =
  | "action"
  | "address"
  | "amount"
  | "block"
  | "chain"
  | "cluster"
  | "code"
  | "count"
  | "decoded"
  | "gas"
  | "selector"
  | "skill"
  | "sourceHost"
  | "status"
  | "slot"
  | "token"
  | "txId";

export type FactRole =
  | "contract"
  | "decimals"
  | "error"
  | "from"
  | "metadata"
  | "native"
  | "null"
  | "owner"
  | "primary"
  | "recipient"
  | "results"
  | "secondary"
  | "spender"
  | "staged"
  | "to"
  | "tx";

export type FactSource = "args" | "decoded" | "label" | "result";

export type ToolFact = {
  kind: FactKind;
  role?: FactRole;
  value: string;
  label?: string;
  source: FactSource;
};

export type ToolOperation = {
  id: string;
  facts: ToolFact[];
  confidence: ToolConfidence;
  rawLabel: string;
  /**
   * Title that overrides the descriptor's. Only for families whose title
   * carries payload data (e.g. a delegation's child label), which a static
   * `fixedTitle` cannot express.
   */
  title?: string;
  /**
   * Forces the failed (red X) presentation. Families whose failure signal is
   * not a `failed`/`error` status fact set this explicitly.
   */
  failed?: boolean;
};

export type ToolContext = {
  rawLabel: string;
  parsedArgs: unknown;
  result: unknown;
  resultRecord: Record<string, unknown> | null;
  relatedResultRecords: Record<string, unknown>[];
};

export type ToolMatcher = (ctx: ToolContext) => ToolOperation | null;

import { asRecord } from "./normalize";
import type { ToolContext, ToolStepInput } from "./types";

const parseArgsText = (argsText?: string): unknown => {
  if (!argsText || argsText === "undefined") return undefined;
  try {
    return JSON.parse(argsText);
  } catch {
    return undefined;
  }
};

const unwrapEnvelope = (value: unknown): unknown => {
  const record = asRecord(value);
  if (!record) return value;
  if (record.is_error === true || "error" in record) return value;

  if ("__aomi_tool_value" in record) {
    return unwrapEnvelope(record.__aomi_tool_value);
  }
  if ("__aomi_tool_return" in record) {
    return unwrapEnvelope(record.__aomi_tool_return);
  }
  if ("__aomi_tool_routes" in record && "value" in record) {
    return unwrapEnvelope(record.value);
  }
  if ("RoutedToolReturn" in record && "value" in record) {
    return unwrapEnvelope(record.value);
  }

  return value;
};

export const unwrapToolStep = ({
  toolName,
  argsText,
  result,
  relatedResults,
}: ToolStepInput): ToolContext => {
  const parsedArgs = parseArgsText(argsText);
  const unwrapped =
    typeof result === "string" ? { args: result } : unwrapEnvelope(result);
  const relatedResultRecords = (relatedResults ?? [])
    .map(unwrapEnvelope)
    .map(asRecord)
    .filter((record): record is Record<string, unknown> => record !== null);

  return {
    rawLabel: toolName,
    parsedArgs,
    result: unwrapped,
    resultRecord: asRecord(unwrapped),
    relatedResultRecords,
  };
};

import { getChainInfo, SUPPORTED_CHAINS } from "@aomi-labs/react";

import type { FactRole, FactSource, ToolFact } from "./types";

export const asRecord = (value: unknown): Record<string, unknown> | null =>
  typeof value === "object" && value !== null
    ? (value as Record<string, unknown>)
    : null;

export const asString = (value: unknown): string | undefined =>
  typeof value === "string" && value.length > 0 ? value : undefined;

export const asNumber = (value: unknown): number | undefined =>
  typeof value === "number" && Number.isFinite(value) ? value : undefined;

export const asInteger = (value: unknown): number | undefined => {
  if (typeof value === "number" && Number.isInteger(value)) return value;
  if (typeof value !== "string" || !/^\d+$/.test(value)) return undefined;
  const parsed = Number(value);
  return Number.isSafeInteger(parsed) ? parsed : undefined;
};

export const humanize = (value: string): string => {
  const readable = value
    .replace(/[_-]+/g, " ")
    .replace(/([a-z0-9])([A-Z])/g, "$1 $2")
    .trim();
  if (!readable) return "Tool";
  return readable.charAt(0).toUpperCase() + readable.slice(1);
};

export const uniqueFacts = (facts: ToolFact[]): ToolFact[] => {
  const seen = new Set<string>();
  return facts.filter((fact) => {
    const key = `${fact.kind}:${fact.role ?? ""}:${fact.label ?? fact.value}`;
    const normalized = key.toLowerCase();
    if (seen.has(normalized)) return false;
    seen.add(normalized);
    return true;
  });
};

const normalizeChainLabel = (value: string): string =>
  value.toLowerCase().replace(/[_-]+/g, " ").trim();

const chainInfoFromName = (name: string | undefined) => {
  if (!name) return undefined;
  const normalized = normalizeChainLabel(name);
  return SUPPORTED_CHAINS.find(
    (chain) =>
      normalizeChainLabel(chain.name) === normalized ||
      chain.ticker.toLowerCase() === normalized,
  );
};

export const chainFact = (
  chainId: unknown,
  chainName?: unknown,
  source: FactSource = "result",
): ToolFact | null => {
  const id = asNumber(chainId);
  const name = asString(chainName);
  const chain = id != null ? getChainInfo(id) : chainInfoFromName(name);
  const resolvedId = chain?.id ?? id;
  if (resolvedId == null && !name) return null;

  return {
    kind: "chain",
    value: resolvedId != null ? String(resolvedId) : (name ?? ""),
    label: chain?.name ?? (name ? humanize(name) : `chain ${id}`),
    source,
  };
};

export const chainFactFromRecord = (
  record: Record<string, unknown> | null | undefined,
  source: FactSource = "result",
): ToolFact | null => {
  if (!record) return null;
  return chainFact(
    record.chain_id,
    record.chain_name ?? record.chain ?? record.network,
    source,
  );
};

/** Resolve an explicit chain name embedded in a model-authored tool topic.
 * Longest names win, so "Base Sepolia" is not reduced to "Base". Tickers are
 * intentionally excluded because token symbols such as ETH are ambiguous. */
export const chainFactFromText = (
  value: string,
  source: FactSource = "label",
): ToolFact | null => {
  const searchable = ` ${value
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, " ")
    .trim()} `;
  const chains = [...SUPPORTED_CHAINS].sort(
    (left, right) => right.name.length - left.name.length,
  );
  const chain = chains.find((candidate) => {
    const name = candidate.name
      .toLowerCase()
      .replace(/[^a-z0-9]+/g, " ")
      .trim();
    return name.length > 0 && searchable.includes(` ${name} `);
  });
  return chain ? chainFact(chain.id, chain.name, source) : null;
};

const ZERO_ADDRESS = "0x0000000000000000000000000000000000000000";

export const normalizeAddress = (value: unknown): string | null => {
  if (typeof value !== "string") return null;
  const lower = value.toLowerCase();
  return /^0x[a-f0-9]{40}$/.test(lower) ? lower : null;
};

export const addressFact = (
  value: unknown,
  role: FactRole,
  source: FactSource = "result",
): ToolFact | null => {
  const address = normalizeAddress(value);
  if (!address) return null;
  return {
    kind: "address",
    role: address === ZERO_ADDRESS ? "null" : role,
    value: address,
    source,
  };
};

export const tokenFact = (
  symbol: unknown,
  source: FactSource = "result",
): ToolFact | null => {
  const value = asString(symbol);
  return value ? { kind: "token", value, source } : null;
};

export const amountFact = (
  value: unknown,
  unit?: string,
  source: FactSource = "result",
): ToolFact | null => {
  const raw =
    typeof value === "bigint"
      ? value.toString()
      : typeof value === "number" && Number.isFinite(value)
        ? String(value)
        : asString(value);
  if (!raw) return null;
  return {
    kind: "amount",
    value: raw,
    label: unit ? `${raw} ${unit}` : raw,
    source,
  };
};

export const statusFact = (
  value: unknown,
  source: FactSource = "result",
): ToolFact | null => {
  if (value === true) return { kind: "status", value: "success", source };
  if (value === false) return { kind: "status", value: "failed", source };
  const raw = asString(value);
  if (!raw) return null;
  const normalized = raw.toLowerCase().replace(/[_-]+/g, " ");
  if (normalized === "pending approval") {
    return { kind: "status", value: "pending_approval", source };
  }
  if (normalized.includes("pending")) {
    return { kind: "status", value: "pending", source };
  }
  if (normalized.includes("queued")) {
    return { kind: "status", value: "queued", source };
  }
  if (normalized.includes("success") || normalized.includes("complete")) {
    return { kind: "status", value: "success", source };
  }
  if (normalized.includes("fail") || normalized.includes("error")) {
    return { kind: "status", value: "failed", source };
  }
  if (normalized.includes("revoked")) {
    return { kind: "status", value: "revoked", source };
  }
  return { kind: "status", value: raw, label: humanize(raw), source };
};

export const selectorFact = (
  value: unknown,
  label?: string,
  source: FactSource = "decoded",
): ToolFact | null => {
  const selector =
    typeof value === "string" && value.startsWith("0x") && value.length >= 10
      ? value.slice(0, 10).toLowerCase()
      : null;
  return selector ? { kind: "selector", value: selector, label, source } : null;
};

export const calldataWord = (input: string, index: number): string | null => {
  const start = 10 + index * 64;
  const word = input.slice(start, start + 64);
  return word.length === 64 ? word : null;
};

export const addressFromWord = (word: string | null): string | null => {
  if (!word) return null;
  return normalizeAddress(`0x${word.slice(24)}`);
};

export const bigintFromWord = (word: string | null): string | null => {
  if (!word) return null;
  try {
    return BigInt(`0x${word}`).toString();
  } catch {
    return null;
  }
};

export const decodedValue = (result: Record<string, unknown>): unknown => {
  const decodedRoot = asRecord(result.result_decoded);
  const decoded = asRecord(decodedRoot?.decoded);
  return decoded?.decoded;
};

export const topicTokenFact = (topic: string): ToolFact | null => {
  const matches = topic.match(/\b[A-Z][A-Z0-9]{1,9}\b/g);
  const ignored = new Set(["URL", "USD"]);
  const token = matches?.find((match) => !ignored.has(match));
  return token ? { kind: "token", value: token, source: "label" } : null;
};

export const hostnameFromUrl = (urlText: string): string | null => {
  try {
    return new URL(urlText).hostname.replace(/^www\./, "");
  } catch {
    return null;
  }
};

import {
  chainFact,
  asRecord,
  asString,
  topicTokenFact,
  tokenFact,
  uniqueFacts,
} from "./normalize";
import {
  matchChainContext,
  matchError,
  matchNativeBalance,
  matchSkillActivation,
  matchTokenLookup,
  matchWebSearch,
} from "./families/simple";
import {
  matchEvmPendingApproval,
  matchEvmSimulation,
  matchStagedTx,
} from "./families/evm-tx";
import {
  matchLifiApproval,
  matchLifiQuote,
  matchLifiSwapPrep,
} from "./families/lifi";
import { matchJupiterSwapPrep } from "./families/jupiter";
import { matchSvmContext, matchSvmTokenHoldings } from "./families/svm";
import { matchSvmPendingApproval, matchSvmSimulation } from "./families/svm-tx";
import { matchEvmCall } from "./families/evm-call";
import { matchTaskDelegation } from "./families/task";
import { presentOperation } from "./present";
import type {
  InterpretedToolStep,
  ToolConfidence,
  ToolContext,
  ToolMatcher,
} from "./types";

const matchers: ToolMatcher[] = [
  matchTaskDelegation,
  matchWebSearch,
  matchSkillActivation,
  matchSvmContext,
  matchSvmTokenHoldings,
  matchChainContext,
  matchNativeBalance,
  matchTokenLookup,
  matchJupiterSwapPrep,
  matchLifiSwapPrep,
  matchLifiQuote,
  matchLifiApproval,
  matchSvmSimulation,
  matchSvmPendingApproval,
  matchStagedTx,
  matchEvmSimulation,
  matchEvmPendingApproval,
  matchEvmCall,
  matchError,
];

const fallbackOperation = (ctx: ToolContext) => {
  const args = asRecord(ctx.parsedArgs);
  const symbol = asString(args?.symbol);
  const facts = uniqueFacts(
    [
      topicTokenFact(ctx.rawLabel),
      chainFact(args?.chain_id, args?.chain_name, "args"),
      symbol ? tokenFact(symbol, "args") : null,
    ].filter((fact): fact is NonNullable<typeof fact> => fact != null),
  );

  const confidence: ToolConfidence = facts.length > 0 ? "medium" : "fallback";

  return {
    id: "fallback",
    facts,
    confidence,
    rawLabel: ctx.rawLabel,
    title: /^(?:evm[_ .-])?get[_ .-]erc20[_ .-]balance$/i.test(ctx.rawLabel)
      ? "Get balance"
      : undefined,
  };
};

export const interpretToolContext = (ctx: ToolContext): InterpretedToolStep => {
  const operation =
    matchers.reduce<ReturnType<ToolMatcher>>(
      (matched, matcher) => matched ?? matcher(ctx),
      null,
    ) ?? fallbackOperation(ctx);

  return presentOperation(operation);
};

export type KnownToken = { symbol: string; decimals: number };

const KNOWN_TOKENS: Readonly<Record<string, KnownToken>> = {
  // Base's canonical native USDC contract, also used by the repository's
  // wallet-impact metadata fixture and chain integrations.
  "8453:0x833589fcd6edb6e08f4c7c32d4f71b54bda02913": {
    symbol: "USDC",
    decimals: 6,
  },
};

export const knownToken = (
  chainId: unknown,
  address: unknown,
): KnownToken | undefined =>
  (typeof chainId === "number" || typeof chainId === "string") &&
  typeof address === "string"
    ? KNOWN_TOKENS[`${chainId}:${address.toLowerCase()}`]
    : undefined;

export const formatTokenUnits = (raw: string, decimals: number): string => {
  const value = BigInt(raw);
  if (decimals === 0) return value.toString();
  const scale = BigInt(10) ** BigInt(decimals);
  const whole = value / scale;
  const fraction = (value % scale)
    .toString()
    .padStart(decimals, "0")
    .replace(/0+$/, "");
  return fraction ? `${whole}.${fraction}` : whole.toString();
};

import {
  addressFact,
  amountFact,
  asRecord,
  asString,
  chainFact,
  chainFactFromRecord,
  hostnameFromUrl,
  statusFact,
  tokenFact,
  topicTokenFact,
  uniqueFacts,
} from "../normalize";
import type { ToolFact, ToolMatcher, ToolOperation } from "../types";

const op = (
  id: string,
  rawLabel: string,
  facts: Array<ToolFact | null>,
  confidence: ToolOperation["confidence"] = "high",
): ToolOperation => ({
  id,
  facts: uniqueFacts(facts.filter((fact): fact is ToolFact => fact != null)),
  confidence,
  rawLabel,
});

const displaySkillLabel = (skillId: string): string | undefined => {
  if (skillId === "lifi_swap") return "Lifi Swap";
  if (skillId === "common_erc20") return "Common Erc20";
  return undefined;
};

export const matchWebSearch: ToolMatcher = ({ rawLabel, resultRecord }) => {
  if (!resultRecord) return null;
  const body = asString(resultRecord.args) ?? asString(resultRecord.result);
  if (!body || !/Found\s+\d+\s+results/i.test(body)) return null;

  const count = body.match(/Found\s+(\d+)\s+results/i)?.[1];
  const firstUrl = body.match(/URL:\s*(https?:\/\/\S+)/i)?.[1];
  const source = firstUrl ? hostnameFromUrl(firstUrl) : null;

  return op("web.search", rawLabel, [
    topicTokenFact(rawLabel),
    count
      ? { kind: "count", role: "results", value: count, source: "result" }
      : null,
    source ? { kind: "sourceHost", value: source, source: "result" } : null,
  ]);
};

export const matchSkillActivation: ToolMatcher = ({
  rawLabel,
  resultRecord,
}) => {
  if (!resultRecord) return null;
  if (!("activated" in resultRecord || "applied_scope" in resultRecord)) {
    return null;
  }

  const activated = Array.isArray(resultRecord.activated)
    ? resultRecord.activated.filter(
        (value): value is string => typeof value === "string",
      )
    : [];

  return op(
    "skill.activate",
    rawLabel,
    activated.length > 0
      ? activated.map((value) => ({
          kind: "skill",
          value,
          label: displaySkillLabel(value),
          source: "result" as const,
        }))
      : [{ kind: "skill", value: "Skill", source: "result" }],
  );
};

export const matchChainContext: ToolMatcher = ({ rawLabel, resultRecord }) => {
  if (!resultRecord) return null;
  if (
    !(
      "supported_chains" in resultRecord ||
      "rpc_endpoint" in resultRecord ||
      "block_number" in resultRecord
    )
  ) {
    return null;
  }

  return op("evm.context", rawLabel, [
    chainFact(resultRecord.chain_id, resultRecord.chain_name),
    typeof resultRecord.block_number === "number"
      ? {
          kind: "block",
          value: String(resultRecord.block_number),
          source: "result",
        }
      : null,
  ]);
};

export const matchNativeBalance: ToolMatcher = ({
  rawLabel,
  parsedArgs,
  resultRecord,
}) => {
  if (!resultRecord) return null;
  const address = addressFact(resultRecord.address, "owner");
  const balance = amountFact(resultRecord.balance_eth, "ETH");
  if (!address || !balance) return null;

  const args = asRecord(parsedArgs);

  return op("evm.account.native_balance", rawLabel, [
    chainFactFromRecord(resultRecord) ?? chainFactFromRecord(args, "args"),
    address,
    { ...balance, role: "native" },
  ]);
};

export const matchTokenLookup: ToolMatcher = ({ rawLabel, resultRecord }) => {
  if (!resultRecord) return null;
  if (!("found" in resultRecord && "contracts" in resultRecord)) return null;

  const contracts = Array.isArray(resultRecord.contracts)
    ? resultRecord.contracts
        .map(asRecord)
        .filter((item): item is Record<string, unknown> => !!item)
    : [];
  const first = contracts[0];
  const found = resultRecord.found === true;

  return op(`evm.contract.lookup.${found ? "found" : "missing"}`, rawLabel, [
    chainFactFromRecord(first) ?? chainFactFromRecord(resultRecord),
    tokenFact(first?.symbol) ?? topicTokenFact(rawLabel),
  ]);
};

export const matchError: ToolMatcher = ({ rawLabel, resultRecord }) => {
  if (!resultRecord) return null;
  const rawError = resultRecord.error;
  if (!(resultRecord.is_error === true || rawError)) return null;
  const errorRecord = asRecord(rawError);
  const code =
    asString(resultRecord.code) ??
    asString(errorRecord?.code) ??
    asString(errorRecord?.type);

  return {
    ...op("tool.error", rawLabel, [
      statusFact("failed"),
      code
        ? { kind: "code", role: "error", value: code, source: "result" }
        : null,
    ]),
    title: /^(?:evm[_ .-])?get[_ .-]erc20[_ .-]balance$/i.test(rawLabel)
      ? "Get balance"
      : undefined,
  };
};

import { EVM_SELECTOR_REGISTRY } from "@/components/assistant-ui/tool-registry";

import {
  addressFact,
  addressFromWord,
  amountFact,
  asString,
  bigintFromWord,
  calldataWord,
  chainFactFromRecord,
  decodedValue,
  selectorFact,
  topicTokenFact,
  uniqueFacts,
} from "../normalize";
import type { ToolFact, ToolMatcher, ToolOperation } from "../types";
import { formatTokenUnits, knownToken } from "../token-registry";

const op = (
  id: string,
  rawLabel: string,
  facts: Array<ToolFact | null>,
  confidence: ToolOperation["confidence"] = "high",
): ToolOperation => ({
  id,
  facts: uniqueFacts(facts.filter((fact): fact is ToolFact => fact != null)),
  confidence,
  rawLabel,
});

export const matchEvmCall: ToolMatcher = ({ rawLabel, resultRecord }) => {
  const tx =
    resultRecord && typeof resultRecord.tx === "object"
      ? (resultRecord.tx as Record<string, unknown>)
      : null;
  const input = asString(tx?.input);
  if (!resultRecord || !tx || !input) return null;
  const selector = selectorFact(input);
  if (!selector) return null;

  const selectorMeta = EVM_SELECTOR_REGISTRY[selector.value];
  const firstAddress = addressFromWord(calldataWord(input, 0));
  const secondAddress = addressFromWord(calldataWord(input, 1));
  const secondAmount = bigintFromWord(calldataWord(input, 1));
  const decoded = decodedValue(resultRecord);
  const token = knownToken(tx.chain_id, tx.to);

  if (selectorMeta?.kind === "erc20_balance") {
    return op("evm.call.erc20.balance_of", rawLabel, [
      chainFactFromRecord(tx),
      topicTokenFact(rawLabel),
      addressFact(firstAddress, "owner", "decoded"),
    ]);
  }

  if (selectorMeta?.kind === "erc20_metadata") {
    const isDecimals = selectorMeta.name === "decimals";
    return op(
      isDecimals ? "evm.call.erc20.decimals" : "evm.call.erc20.metadata",
      rawLabel,
      [
        chainFactFromRecord(tx),
        topicTokenFact(rawLabel),
        { ...selector, label: selectorMeta.name, role: "metadata" },
        decoded != null
          ? {
              kind: "decoded",
              role: isDecimals ? "decimals" : undefined,
              value: String(decoded),
              label: isDecimals ? `${String(decoded)} decimals` : undefined,
              source: "decoded",
            }
          : null,
      ],
    );
  }

  if (selectorMeta?.kind === "erc20_allowance") {
    return op("evm.call.erc20.allowance", rawLabel, [
      chainFactFromRecord(tx),
      topicTokenFact(rawLabel),
      addressFact(firstAddress, "owner", "decoded"),
      addressFact(secondAddress, "spender", "decoded"),
    ]);
  }

  if (selectorMeta?.kind === "erc20_approve") {
    return op("evm.call.erc20.approve", rawLabel, [
      chainFactFromRecord(tx),
      topicTokenFact(rawLabel),
      addressFact(firstAddress, "spender", "decoded"),
      amountFact(
        secondAmount && token
          ? formatTokenUnits(secondAmount, token.decimals)
          : secondAmount,
        token?.symbol ?? "raw units",
        "decoded",
      ),
    ]);
  }

  if (selectorMeta?.kind === "erc20_transfer") {
    return op("evm.call.erc20.transfer", rawLabel, [
      chainFactFromRecord(tx),
      topicTokenFact(rawLabel),
      addressFact(firstAddress, "recipient", "decoded"),
      amountFact(secondAmount, undefined, "decoded"),
    ]);
  }

  return op(
    "evm.call.generic",
    rawLabel,
    [
      chainFactFromRecord(tx),
      addressFact(tx.from, "from"),
      addressFact(tx.to, "to"),
    ],
    "medium",
  );
};

import { EVM_SELECTOR_REGISTRY } from "@/components/assistant-ui/tool-registry";

import {
  asNumber,
  asRecord,
  asString,
  chainFact,
  chainFactFromRecord,
  chainFactFromText,
  humanize,
  selectorFact,
  statusFact,
  uniqueFacts,
} from "../normalize";
import type { ToolFact, ToolMatcher, ToolOperation } from "../types";

const op = (
  id: string,
  rawLabel: string,
  facts: Array<ToolFact | null>,
): ToolOperation => ({
  id,
  facts: uniqueFacts(facts.filter((fact): fact is ToolFact => fact != null)),
  confidence: "high",
  rawLabel,
});

const stagedActionId = (action: string): string =>
  action
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "_")
    .replace(/^_+|_+$/g, "") || "custom";

const canonicalToolName = (rawLabel: string): string =>
  rawLabel.toLowerCase().split(/[.:/]/).at(-1) ?? "";

const isTool = (rawLabel: string, name: string): boolean =>
  canonicalToolName(rawLabel) === name;

const failedFact = (resultRecord: Record<string, unknown> | null) =>
  resultRecord && (resultRecord.is_error === true || resultRecord.error)
    ? statusFact("failed")
    : null;

const associatedChain = (
  records: Record<string, unknown>[],
  requestedIds: number[],
): ToolFact | null => {
  const chains = records
    .filter((record) => {
      const pendingId = asNumber(record.pending_tx_id);
      return pendingId != null && requestedIds.includes(pendingId);
    })
    .map((record) => chainFactFromRecord(record))
    .filter((fact): fact is ToolFact => fact != null);
  const unique = uniqueFacts(chains);
  return unique.length === 1 ? unique[0] : null;
};

export const matchStagedTx: ToolMatcher = ({
  rawLabel,
  parsedArgs,
  resultRecord,
}) => {
  const namedStage = isTool(rawLabel, "evm_stage_tx");
  if (
    !namedStage &&
    (!resultRecord || resultRecord.current_lifecycle !== "queued")
  ) {
    return null;
  }

  const args = asRecord(parsedArgs);
  const chain =
    chainFactFromRecord(resultRecord) ?? chainFactFromRecord(args, "args");
  if (!namedStage && !chain) return null;

  const data = asString(resultRecord?.data);
  const selector = data ? selectorFact(data) : null;
  const selectorMeta = selector ? EVM_SELECTOR_REGISTRY[selector.value] : null;
  const kind = asString(resultRecord?.kind) ?? asString(args?.kind);
  const action = selectorMeta?.chip ?? kind;
  const pendingTxId = asNumber(resultRecord?.pending_tx_id);

  return op(`evm.tx.stage.${stagedActionId(action ?? "custom")}`, rawLabel, [
    chain,
    action
      ? {
          kind: "action",
          value: action,
          label: humanize(action),
          source: selectorMeta ? "decoded" : "result",
        }
      : null,
    pendingTxId != null
      ? {
          kind: "count",
          role: "tx",
          value: "1",
          source: "result",
        }
      : null,
    failedFact(resultRecord) ?? statusFact(resultRecord?.current_lifecycle),
  ]);
};

export const matchEvmSimulation: ToolMatcher = ({
  rawLabel,
  parsedArgs,
  resultRecord,
  relatedResultRecords,
}) => {
  const namedSimulation = isTool(rawLabel, "simulate_batch");
  if (!resultRecord && !namedSimulation) return null;
  const sim =
    typeof resultRecord?.simulation === "object" && resultRecord.simulation
      ? (resultRecord.simulation as Record<string, unknown>)
      : null;
  if (
    !namedSimulation &&
    !(sim || (resultRecord && "batch_success" in resultRecord))
  )
    return null;

  const args = asRecord(parsedArgs);
  const requestedIds = Array.isArray(args?.transactions)
    ? args.transactions
        .map(asRecord)
        .map((transaction) => asNumber(transaction?.id))
        .filter((id): id is number => id != null)
    : Array.isArray(args?.tx_ids)
      ? args.tx_ids.filter((id): id is number => typeof id === "number")
      : [];
  const chain =
    chainFactFromRecord(resultRecord) ??
    chainFact(undefined, sim?.network) ??
    chainFactFromRecord(args, "args") ??
    associatedChain(relatedResultRecords, requestedIds);
  if (!namedSimulation && !chain) return null;

  const explicitBatchSuccess =
    sim?.batch_success ?? resultRecord?.batch_success;
  const simulationStatus =
    explicitBatchSuccess !== undefined
      ? explicitBatchSuccess
      : sim && "err" in sim
        ? sim.err == null
        : resultRecord?.last_batch_status;
  const gas = asNumber(sim?.total_gas) ?? asNumber(resultRecord?.total_gas);
  const steps = Array.isArray(sim?.steps)
    ? sim.steps.length
    : Array.isArray(resultRecord?.tx_ids)
      ? resultRecord.tx_ids.length
      : requestedIds.length || undefined;

  return op("evm.tx.simulate_batch", rawLabel, [
    chain,
    steps != null
      ? {
          kind: "count",
          role: "tx",
          value: String(steps),
          source: "result",
        }
      : null,
    failedFact(resultRecord) ?? statusFact(simulationStatus),
    gas != null
      ? {
          kind: "gas",
          value: String(gas),
          source: "result",
        }
      : null,
  ]);
};

export const matchEvmPendingApproval: ToolMatcher = ({
  rawLabel,
  parsedArgs,
  resultRecord,
  relatedResultRecords,
}) => {
  const namedCommit = isTool(rawLabel, "evm_commit_txs");
  if (
    (!namedCommit &&
      (!resultRecord || resultRecord.status !== "pending_approval")) ||
    resultRecord?.chain_kind === "svm" ||
    Array.isArray(resultRecord?.svm_ix_ids)
  ) {
    return null;
  }

  const args = asRecord(parsedArgs);
  const txIds = Array.isArray(resultRecord?.tx_ids)
    ? resultRecord.tx_ids
    : Array.isArray(args?.tx_ids)
      ? args.tx_ids
      : [];
  const stagedIds = new Set(
    txIds.filter(
      (value): value is number =>
        typeof value === "number" && Number.isInteger(value),
    ),
  );
  const chain =
    chainFactFromRecord(resultRecord) ??
    chainFactFromRecord(args, "args") ??
    associatedChain(relatedResultRecords, [...stagedIds]) ??
    chainFactFromText(rawLabel);
  const outcome = asRecord(resultRecord?.tx_outcome);
  const txHash = asString(outcome?.txHash);

  return op("evm.tx.pending_approval", rawLabel, [
    chain,
    txIds.length > 0
      ? {
          kind: "count",
          role: "tx",
          value: String(txIds.length),
          source: "result",
        }
      : null,
    txHash
      ? {
          kind: "txId",
          value: txHash,
          source: "result",
        }
      : null,
    // The canonical model rewrites the tool result on resolution, so a record
    // still shaped as pending_approval is pending; an inline tx_outcome only
    // appears on pre-cutover persisted results and still wins when present.
    failedFact(resultRecord) ??
      statusFact(
        outcome?.status ??
          resultRecord?.status ??
          (resultRecord ? undefined : "pending"),
      ),
  ]);
};

import {
  amountFact,
  asInteger,
  asRecord,
  asString,
  uniqueFacts,
} from "../normalize";
import type { ToolFact, ToolMatcher } from "../types";

const KNOWN_MAINNET_TOKEN_SYMBOLS: Record<string, string> = {
  EPjFWdd5AufqSSqeM2qN1xzybapC8G4wEGGkZwyTDt1v: "USDC",
};

export const svmClusterFact = (
  value: unknown,
  fallback = "mainnet-beta",
): ToolFact => {
  const cluster = asString(value) ?? fallback;
  const normalized = cluster.toLowerCase().replace(/^solana:/, "");
  const label = normalized.includes("devnet")
    ? "Solana Devnet"
    : normalized.includes("testnet")
      ? "Solana Testnet"
      : "Solana";
  return {
    kind: "cluster",
    value: cluster,
    label,
    source: "result",
  };
};

export const matchSvmContext: ToolMatcher = ({ rawLabel, resultRecord }) => {
  if (!resultRecord) return null;
  const slot = asInteger(resultRecord.current_slot);
  const cluster = asString(resultRecord.cluster);
  const supportedClusters = resultRecord.supported_clusters;
  if (!cluster || (slot == null && !Array.isArray(supportedClusters))) {
    return null;
  }

  return {
    id: "svm.context",
    facts: uniqueFacts([
      svmClusterFact(cluster),
      ...(slot == null
        ? []
        : [
            {
              kind: "slot" as const,
              value: String(slot),
              source: "result" as const,
            },
          ]),
    ]),
    confidence: "high",
    rawLabel,
  };
};

const tokenAmountFact = (
  holding: Record<string, unknown>,
  cluster: unknown,
): ToolFact | null => {
  const mint = asString(holding.mint);
  const amount =
    asString(holding.ui_amount_string) ??
    asString(holding.uiAmountString) ??
    (typeof holding.uiAmount === "number"
      ? String(holding.uiAmount)
      : undefined);
  if (!amount) return null;

  const clusterName = asString(cluster)?.toLowerCase();
  const isMainnet =
    clusterName === "mainnet-beta" ||
    clusterName === "mainnet" ||
    clusterName === "solana:mainnet";
  const symbol =
    asString(holding.symbol) ??
    (mint && isMainnet ? KNOWN_MAINNET_TOKEN_SYMBOLS[mint] : undefined);
  const fact = amountFact(amount, symbol);
  return fact ? { ...fact, role: "primary" } : null;
};

const rawTokenHolding = (value: unknown): Record<string, unknown> | null => {
  const keyedAccount = asRecord(value);
  const account = asRecord(keyedAccount?.account);
  const data = asRecord(account?.data);
  const parsed = asRecord(data?.parsed);
  const info = asRecord(parsed?.info);
  const tokenAmount = asRecord(info?.tokenAmount);
  if (!info || !tokenAmount) return null;
  return {
    mint: info.mint,
    uiAmount: tokenAmount.uiAmount,
    uiAmountString: tokenAmount.uiAmountString,
  };
};

const accountsFrom = (value: unknown): unknown[] => {
  const record = asRecord(value);
  return Array.isArray(record?.accounts) ? record.accounts : [];
};

export const matchSvmTokenHoldings: ToolMatcher = ({
  rawLabel,
  resultRecord,
}) => {
  if (!resultRecord || !asString(resultRecord.owner)) return null;

  const compactHoldings = Array.isArray(resultRecord.holdings)
    ? resultRecord.holdings
        .map(asRecord)
        .filter(
          (holding): holding is Record<string, unknown> => holding != null,
        )
    : [];
  const rawAccounts = [
    ...(Array.isArray(resultRecord.accounts) ? resultRecord.accounts : []),
    ...accountsFrom(resultRecord.token_program),
    ...accountsFrom(resultRecord.token_2022_program),
  ];
  if (compactHoldings.length === 0 && rawAccounts.length === 0) return null;

  const holdings =
    compactHoldings.length > 0
      ? compactHoldings
      : rawAccounts
          .map(rawTokenHolding)
          .filter(
            (holding): holding is Record<string, unknown> => holding != null,
          );
  const amounts = holdings
    .map((holding) => tokenAmountFact(holding, resultRecord.cluster))
    .filter((fact): fact is ToolFact => fact != null);

  return {
    id: "svm.account.token_holdings",
    facts: uniqueFacts([svmClusterFact(resultRecord.cluster), ...amounts]),
    confidence: "high",
    rawLabel,
  };
};

import { asRecord, asString, statusFact, uniqueFacts } from "../normalize";
import type { ToolFact, ToolMatcher, ToolOperation } from "../types";

const op = (
  id: string,
  rawLabel: string,
  facts: Array<ToolFact | null>,
): ToolOperation => ({
  id,
  facts: uniqueFacts(facts.filter((fact): fact is ToolFact => fact != null)),
  confidence: "high",
  rawLabel,
});

const txCountFact = (ids: unknown): ToolFact | null =>
  Array.isArray(ids)
    ? {
        kind: "count",
        role: "tx",
        value: String(ids.length),
        source: "result",
      }
    : null;

const isSvmSimulation = (
  result: Record<string, unknown>,
  simulation: Record<string, unknown> | null,
): boolean => {
  if (result.chain_kind === "svm") return true;
  if (!Array.isArray(result.ix_ids)) return false;

  const batchStatus = asString(result.last_batch_status)?.toLowerCase();
  return Boolean(
    batchStatus?.includes("svm") ||
    simulation?.units_consumed != null ||
    Array.isArray(simulation?.logs),
  );
};

export const matchSvmSimulation: ToolMatcher = ({ rawLabel, resultRecord }) => {
  if (!resultRecord) return null;
  const simulation = asRecord(resultRecord.simulation);
  if (!simulation || !isSvmSimulation(resultRecord, simulation)) return null;

  const simulationStatus =
    "err" in simulation
      ? simulation.err == null
      : resultRecord.last_batch_status;

  return op("svm.tx.simulate_batch", rawLabel, [
    txCountFact(resultRecord.ix_ids),
    statusFact(simulationStatus),
  ]);
};

export const matchSvmPendingApproval: ToolMatcher = ({
  rawLabel,
  resultRecord,
}) => {
  if (
    !resultRecord ||
    !(
      resultRecord.chain_kind === "svm" ||
      Array.isArray(resultRecord.svm_ix_ids)
    ) ||
    resultRecord.status !== "pending_approval"
  ) {
    return null;
  }

  return op("svm.tx.pending_approval", rawLabel, [
    txCountFact(resultRecord.svm_ix_ids),
    statusFact(resultRecord.status),
  ]);
};

